[meta]
name = Old Harrowmere
ambient = 0.5 0.4 0.3
fog = 0.2 0.13 0.07
fog_range = 14 110
torch = 8 0.95 0.75 0.5
start = 4 3 0
default = a
entity_floor = auto
edge_top = 24
edge_tex = cavern_rock
model_range = 60
vault = 24
vault_tex = cavern_rock

// The first Harrowmere, sunk into a cavern under the town that was raised on its ruins: below the Sodden
// Pall's cistern its wall gives way onto a sheer chasm, the drowned city standing in it in tiers. From
// the Breach Landing the Cliff Stair winds down the north wall to the bell-keepers' terrace; a bridge
// runs out to the Bell Tower, its stair winding down round the tower's core to the Aqueduct, which
// carries you west to the Colonnade. From there the Grand Stair goes down to the Drowned Plaza, lit by
// the one shaft of daylight that falls from a crack in the cavern's vault far overhead. Below the plaza
// the Keystone, the giant the first city was raised on, lies in its Foundation Court; behind it a lift
// climbs the old gallery's shaft back up to the landing. Stone Golems stand like statues until you come
// close, and the Sunken Sextons ring their bells to wake them. Over it all hangs the vault of the cavern,
// rough rock 24 m up with stalactites hanging from it (`vault`); the shaft falls through a crack in it.

